// Spy records which operation handlers the generated reconciler dispatched to
// and supplies the result each one returns. A real module puts reconciliation
// logic in these handlers; the fixture records the call instead, so a test
// asserts on which branch the dispatch loop took rather than on what the
// handler did.
type Spy struct {
	mu sync.Mutex

	// calls holds the operation names in dispatch order.
	calls []string

	// results maps an operation name to what its handler returns. An absent
	// entry means the handler succeeds with no requeue.
	results map[string]Result
}

// Result is what a spied handler returns to the generated reconciler: a
// custom requeue delay in seconds and an error.
type Result struct {
	RequeueDelay int64
	Err          error
}

// NewSpy returns a Spy whose handlers all succeed.
func NewSpy() *Spy {
	return &Spy{results: make(map[string]Result)}
}

// SetResult makes the named operation return result instead of succeeding.
// Operation names are "create", "update", and "delete".
func (s *Spy) SetResult(operation string, result Result) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.results[operation] = result
}

// Calls returns the operations dispatched so far, in order.
func (s *Spy) Calls() []string {
	s.mu.Lock()
	defer s.mu.Unlock()
	return append([]string(nil), s.calls...)
}

// record notes a dispatch and returns whatever SetResult installed for that
// operation, or a success with no requeue when nothing was installed.
func (s *Spy) record(operation string) (int64, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.calls = append(s.calls, operation)
	result := s.results[operation]
	return result.RequeueDelay, result.Err
}

// activeSpy is the spy the handlers below report to. A test installs its own
// through InstallSpy before driving the reconciler.
var activeSpy = NewSpy()

// InstallSpy makes spy the recipient of every handler call and returns a
// function restoring the previous one.
func InstallSpy(spy *Spy) func() {
	previous := activeSpy
	activeSpy = spy
	return func() { activeSpy = previous }
}

